package app.loveu;
import android.app.*;import android.content.*;import android.os.*;import android.provider.Settings;import org.json.*;import java.time.*;
public final class TimerService extends Service {
 public static final String ACTION_START="app.loveu.START",ACTION_PAUSE="app.loveu.PAUSE",ACTION_RESUME="app.loveu.RESUME",ACTION_FINISH="app.loveu.FINISH",ACTION_CANCEL="app.loveu.CANCEL";private static final String CHANNEL="session";private static final int ID=7;private final Handler handler=new Handler(Looper.getMainLooper());
 public static void send(Context c,String action){Intent i=new Intent(c,TimerService.class).setAction(action);if(ACTION_START.equals(action))c.startForegroundService(i);else c.startService(i);}
 public IBinder onBind(Intent i){return null;}
 public void onCreate(){super.onCreate();((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(new NotificationChannel(CHANNEL,Language.ui("计时状态"),NotificationManager.IMPORTANCE_LOW));}
 private int boot(){return Settings.Global.getInt(getContentResolver(),Settings.Global.BOOT_COUNT,0);}
 private PendingIntent action(String a,int id){return PendingIntent.getService(this,id,new Intent(this,TimerService.class).setAction(a),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 private void notifyState(boolean paused,boolean review){Notification.Builder b=new Notification.Builder(this,CHANNEL).setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentTitle(Language.ui("Love U")).setContentText(Language.ui(review?"记录待确认":paused?"计时已暂停":"计时进行中")).setVisibility(Notification.VISIBILITY_SECRET).setOngoing(true).addAction(new Notification.Action.Builder(null,paused?"继续":"暂停",action(paused?ACTION_RESUME:ACTION_PAUSE,1)).build()).addAction(new Notification.Action.Builder(null,"结束",action(ACTION_FINISH,2)).build());Intent open=getPackageManager().getLaunchIntentForPackage(getPackageName());if(open!=null)b.setContentIntent(PendingIntent.getActivity(this,3,open,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT));startForeground(ID,b.build());}
 public int onStartCommand(Intent intent,int flags,int startId){notifyState(false,false);try{synchronized(Vault.class){Vault v=new Vault(this);JSONObject root=v.read();JSONObject snapshot=root.optJSONObject("timer");String a=intent==null?null:intent.getAction();long now=SystemClock.elapsedRealtime();String completedId=null;
 if(ACTION_START.equals(a)&&snapshot==null){Domain.Timer t=new Domain.Timer();t.start(System.currentTimeMillis(),now,boot());snapshot=new JSONObject().put("state",Vault.timerToJson(t)).put("needsReview",false).put("startZone",ZoneId.systemDefault().getId());JSONObject defaults=root.getJSONObject("settings");for(String k:new String[]{"method","partner","place","lat","lon","locationAccuracy","locationCapturedAt"}){Object value=intent.hasExtra(k)?intent.getExtras().get(k):defaults.opt(k);snapshot.put(k,value==null?JSONObject.NULL:value);}root.put("timer",snapshot);v.write(root);}
 if(snapshot!=null){Domain.Timer t=Vault.timerFromJson(snapshot.getJSONObject("state"));boolean uncertain=snapshot.optBoolean("needsReview")||t.rebooted(boot())||now<t.lastResume||System.currentTimeMillis()-t.startWall>10800000L||t.duration(now)>10800000L;
 if(uncertain){snapshot.put("needsReview",true);if(!t.paused){if(!t.rebooted(boot())&&now>=t.lastResume)t.pause(now);else t.paused=true;}}
 if(ACTION_CANCEL.equals(a)){root.put("timer",JSONObject.NULL);snapshot=null;}else if(ACTION_PAUSE.equals(a)){t.pause(now);}else if(ACTION_RESUME.equals(a)&&!uncertain){t.resume(now);}else if(ACTION_FINISH.equals(a)&&!uncertain){Domain.Event e=new Domain.Event();e.id="timer:"+t.startWall+":"+t.startElapsed;e.detailsPending=true;completedId=e.id;ZonedDateTime time=SessionTime.start(t.startWall,snapshot.optString("startZone",null),ZoneId.systemDefault());e.date=time.toLocalDate().toString();e.time=time.toLocalTime().withNano(0).toString();e.durationMillis=t.duration(now);e.source="计时";e.method=nullable(snapshot,"method");e.partner=nullable(snapshot,"partner");e.place=nullable(snapshot,"place");if(!snapshot.isNull("lat")&&snapshot.has("lat"))e.latitude=snapshot.getDouble("lat");if(!snapshot.isNull("lon")&&snapshot.has("lon"))e.longitude=snapshot.getDouble("lon");if(snapshot.has("locationAccuracy")&&!snapshot.isNull("locationAccuracy"))e.locationAccuracy=snapshot.getDouble("locationAccuracy");if(snapshot.has("locationCapturedAt")&&!snapshot.isNull("locationCapturedAt"))e.locationCapturedAt=snapshot.getLong("locationCapturedAt");JSONArray events=root.getJSONArray("events");boolean exists=false;for(int n=0;n<events.length();n++)if(e.id.equals(events.getJSONObject(n).optString("id"))){exists=true;break;}if(!exists)events.put(Vault.eventToJson(e));root.put("timer",JSONObject.NULL);snapshot=null;}
 if(snapshot!=null)snapshot.put("state",Vault.timerToJson(t));v.write(root);if(snapshot!=null)notifyState(t.paused,uncertain);}
 Intent changed=new Intent("app.loveu.CHANGED").setPackage(getPackageName());if(completedId!=null)changed.putExtra("completedId",completedId);sendBroadcast(changed);if(snapshot==null){stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();return START_NOT_STICKY;}}
 }catch(Exception e){sendBroadcast(new Intent("app.loveu.CHANGED").setPackage(getPackageName()).putExtra("error","无法保存计时状态"));stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();return START_NOT_STICKY;}handler.removeCallbacks(check);handler.postDelayed(check,60000);return START_STICKY;}
 private final Runnable check=()->onStartCommand(null,0,0);private static String nullable(JSONObject j,String k){return j.isNull(k)?null:j.optString(k,null);}public void onDestroy(){handler.removeCallbacks(check);super.onDestroy();}
}
